<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Maze Discovery — 24 Explorer Bots</title>
<style>
  :root{
    --bg:#0e1116; --panel:#161b22; --ink:#e6edf3; --muted:#8b949e;
    --accent:#58a6ff; --wall:#c9d1d9; --spawn:#3fb950; --exit:#f778ba;
  }
  *{box-sizing:border-box}
  body{
    margin:0; background:var(--bg); color:var(--ink);
    font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;
    display:flex; flex-direction:column; align-items:center; padding:18px;
  }
  h1{font-size:18px; font-weight:600; margin:0 0 12px; letter-spacing:.3px}
  .hud{
    display:flex; gap:10px; flex-wrap:wrap; justify-content:center;
    margin-bottom:14px;
  }
  .stat{
    background:var(--panel); border:1px solid #21262d; border-radius:10px;
    padding:8px 14px; min-width:96px; text-align:center;
  }
  .stat .k{font-size:11px; color:var(--muted); text-transform:uppercase; letter-spacing:.6px}
  .stat .v{font-size:20px; font-weight:700; font-variant-numeric:tabular-nums}
  #reset{
    background:var(--accent); color:#0b1220; border:none; border-radius:10px;
    padding:0 18px; font-size:14px; font-weight:700; cursor:pointer;
  }
  #reset:hover{filter:brightness(1.08)}
  #maze{
    background:var(--panel); border:1px solid #21262d; border-radius:12px;
    padding:10px; line-height:0;
  }
  canvas{display:block; border-radius:6px; background:#0b0f14}
  .legend{margin-top:12px; font-size:12px; color:var(--muted); display:flex; gap:18px}
  .legend b{color:var(--ink)}
  .dot{display:inline-block; width:10px; height:10px; border-radius:50%; vertical-align:middle; margin-right:4px}
</style>
</head>
<body>
  <h1>Maze Discovery — 24 bots explore an unknown maze (Tremaux / DFS)</h1>
  <div class="hud">
    <div class="stat"><div class="k">Completed</div><div class="v" id="completed">0 / 24</div></div>
    <div class="stat"><div class="k">Timer (ticks)</div><div class="v" id="timer">0</div></div>
    <button id="reset">Reset</button>
  </div>
  <div id="maze"><canvas id="cv" width="420" height="420"></canvas></div>
  <div class="legend">
    <span><span class="dot" style="background:var(--spawn)"></span><b>Spawn</b></span>
    <span><span class="dot" style="background:var(--exit)"></span><b>Exit (unknown to bots)</b></span>
    <span>Bots backtrack from dead ends and never re-explore them.</span>
  </div>

<script>
(function(){
  "use strict";

  // ---------- config ----------
  const ROWS = 21, COLS = 21;      // perfect maze, >= 15x15
  const NBOTS = 24;
  const cv = document.getElementById('cv');
  const ctx = cv.getContext('2d');
  const CELL = Math.floor(Math.min(cv.width, cv.height) / COLS); // 20
  const TICK_MS = 90;              // visual tick pacing

  // ---------- seeded RNG (mulberry32) ----------
  function mulberry32(a){
    return function(){
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  // ---------- state ----------
  let grid, spawn, exit, bots, elapsed, currentSeed;
  let autoRun = true;            // paused when programmatic control takes over
  const key = (r,c) => r * COLS + c;

  // all 24 permutations of the four directions -> unique bot preferences
  function permutations(arr){
    if (arr.length <= 1) return [arr.slice()];
    const out = [];
    for (let i = 0; i < arr.length; i++){
      const rest = arr.slice(0, i).concat(arr.slice(i + 1));
      for (const p of permutations(rest)) out.push([arr[i]].concat(p));
    }
    return out;
  }
  const DIRPERMS = permutations(['n','e','s','w']); // exactly 24

  // ---------- maze generation (recursive backtracker) ----------
  function genMaze(rng){
    grid = new Array(ROWS);
    for (let r = 0; r < ROWS; r++){
      grid[r] = new Array(COLS);
      for (let c = 0; c < COLS; c++)
        grid[r][c] = { n:true, e:true, s:true, w:true, seen:false };
    }
    const stack = [{ r:0, c:0 }];
    grid[0][0].seen = true;
    const DIRS = [
      { d:'n', dr:-1, dc:0, opp:'s' },
      { d:'e', dr:0,  dc:1, opp:'w' },
      { d:'s', dr:1,  dc:0, opp:'n' },
      { d:'w', dr:0,  dc:-1, opp:'e' },
    ];
    while (stack.length){
      const cur = stack[stack.length - 1];
      const opts = [];
      for (const D of DIRS){
        const nr = cur.r + D.dr, nc = cur.c + D.dc;
        if (nr >= 0 && nr < ROWS && nc >= 0 && nc < COLS && !grid[nr][nc].seen)
          opts.push({ D, nr, nc });
      }
      if (opts.length){
        const pick = opts[Math.floor(rng() * opts.length)];
        grid[cur.r][cur.c][pick.D.d] = false;      // carve wall out
        grid[pick.nr][pick.nc][pick.D.opp] = false;// and its twin
        grid[pick.nr][pick.nc].seen = true;
        stack.push({ r:pick.nr, c:pick.nc });
      } else {
        stack.pop();
      }
    }
  }

  // ---------- bot movement helpers ----------
  function passable(r, c, d){
    const w = grid[r][c];
    if (d === 'n') return !w.n && r > 0;
    if (d === 's') return !w.s && r < ROWS - 1;
    if (d === 'e') return !w.e && c < COLS - 1;
    if (d === 'w') return !w.w && c > 0;
    return false;
  }
  function stepDir(cur, d){
    if (d === 'n') return { r:cur.r - 1, c:cur.c };
    if (d === 's') return { r:cur.r + 1, c:cur.c };
    if (d === 'e') return { r:cur.r, c:cur.c + 1 };
    return { r:cur.r, c:cur.c - 1 };
  }

  function makeBots(){
    bots = [];
    for (let i = 0; i < NBOTS; i++){
      bots.push({
        id: i,
        prefs: DIRPERMS[i % DIRPERMS.length], // unique exploration order
        pos: { r:spawn.r, c:spawn.c },
        prevPos: { r:spawn.r, c:spawn.c },
        visited: new Set([key(spawn.r, spawn.c)]),
        stack: [{ r:spawn.r, c:spawn.c }],     // DFS backtracking stack (own memory)
        path: [{ r:spawn.r, c:spawn.c }],      // every cell entered, in order
        deadEnds: [],                          // branches marked dead
        finishTick: null,
        finished: false,
        color: 'hsl(' + (i * 15) + ',72%,58%)',
      });
    }
  }

  // Move one bot exactly one cell. Pure DFS on the bot's OWN discovered map:
  //  - step forward into an unvisited passable neighbour, OR
  //  - backtrack (marking the exhausted cell dead) when none remain.
  // Each passage is traversed at most twice (once forward, once back).
  function moveBot(b, t){
    const cur = b.pos;
    let next = null;
    for (const d of b.prefs){
      if (passable(cur.r, cur.c, d)){
        const nb = stepDir(cur, d);
        if (!b.visited.has(key(nb.r, nb.c))){ next = nb; break; }
      }
    }
    if (next){
      b.prevPos = { r:cur.r, c:cur.c };
      b.visited.add(key(next.r, next.c));
      b.stack.push({ r:next.r, c:next.c });
      b.pos = { r:next.r, c:next.c };
      b.path.push({ r:next.r, c:next.c });
      if (next.r === exit.r && next.c === exit.c){
        b.finished = true;
        b.finishTick = t;           // the tick it arrives
      }
    } else {
      // exhausted branch -> record dead, then backtrack
      b.deadEnds.push({ r:cur.r, c:cur.c });
      b.stack.pop();
      if (b.stack.length === 0) return; // fully explored (won't happen before exit)
      const back = b.stack[b.stack.length - 1];
      b.prevPos = { r:cur.r, c:cur.c };
      b.pos = { r:back.r, c:back.c };
      b.path.push({ r:back.r, c:back.c });
    }
  }

  // One deterministic simulation tick. Timer freezes once all bots arrived.
  function step(){
    let anyLeft = false;
    for (let i = 0; i < bots.length; i++){ if (!bots[i].finished){ anyLeft = true; break; } }
    if (!anyLeft) return;           // frozen: no change to elapsed or bot state
    elapsed++;
    const t = elapsed;
    for (const b of bots){ if (!b.finished) moveBot(b, t); }
  }

  // ---------- setup / reset ----------
  function build(seed){
    currentSeed = (typeof seed === 'number' && isFinite(seed))
      ? (seed >>> 0)
      : (Math.floor(Math.random() * 0xFFFFFFFF) >>> 0);
    const rng = mulberry32(currentSeed);
    genMaze(rng);
    spawn = { r:0, c:0 };
    exit  = { r:ROWS - 1, c:COLS - 1 };
    makeBots();
    elapsed = 0;
    acc = 0;
  }

  // ---------- rendering ----------
  function lerp(a, b, t){ return a + (b - a) * t; }

  function draw(alpha){
    const W = cv.width, H = cv.height;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#0b0f14';
    ctx.fillRect(0, 0, W, H);

    // spawn / exit tiles
    ctx.fillStyle = 'rgba(63,185,80,0.28)';
    ctx.fillRect(spawn.c * CELL, spawn.r * CELL, CELL, CELL);
    ctx.fillStyle = 'rgba(247,120,186,0.32)';
    ctx.fillRect(exit.c * CELL, exit.r * CELL, CELL, CELL);

    // walls
    ctx.strokeStyle = getComputedStyle(document.documentElement).getPropertyValue('--wall').trim() || '#c9d1d9';
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    ctx.beginPath();
    for (let r = 0; r < ROWS; r++){
      for (let c = 0; c < COLS; c++){
        const w = grid[r][c];
        const x = c * CELL, y = r * CELL;
        if (w.n){ ctx.moveTo(x, y); ctx.lineTo(x + CELL, y); }
        if (w.w){ ctx.moveTo(x, y); ctx.lineTo(x, y + CELL); }
        if (w.e && c === COLS - 1){ ctx.moveTo(x + CELL, y); ctx.lineTo(x + CELL, y + CELL); }
        if (w.s && r === ROWS - 1){ ctx.moveTo(x, y + CELL); ctx.lineTo(x + CELL, y + CELL); }
      }
    }
    ctx.stroke();

    // bots (interpolated, centred in the corridor)
    const rad = CELL * 0.30;
    for (const b of bots){
      const a = b.finished ? 1 : alpha;
      const cx = (lerp(b.prevPos.c, b.pos.c, a) + 0.5) * CELL;
      const cy = (lerp(b.prevPos.r, b.pos.r, a) + 0.5) * CELL;
      ctx.beginPath();
      ctx.arc(cx, cy, rad, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.fill();
      if (b.finished){
        ctx.lineWidth = 1.5;
        ctx.strokeStyle = '#ffffff';
        ctx.stroke();
      }
    }
  }

  function updateHUD(){
    let done = 0;
    for (const b of bots) if (b.finished) done++;
    document.getElementById('completed').textContent = done + ' / ' + NBOTS;
    document.getElementById('timer').textContent = elapsed;
  }

  // ---------- animation loop (visual only; sim is driven through step) ----------
  let acc = 0, lastTime = null;
  function frame(now){
    if (lastTime === null) lastTime = now;
    let dt = now - lastTime; lastTime = now;
    if (dt > 250) dt = 250;
    let anyLeft = false;
    for (const b of bots) if (!b.finished){ anyLeft = true; break; }
    if (autoRun && anyLeft){
      acc += dt;
      while (acc >= TICK_MS){ step(); acc -= TICK_MS; }
    } else {
      acc = 0;
    }
    const alpha = autoRun ? Math.min(acc / TICK_MS, 1) : 1;
    draw(alpha);
    updateHUD();
    requestAnimationFrame(frame);
  }

  // ---------- public scripting API ----------
  window.game = {
    tick(n){
      autoRun = false;               // hand deterministic control to caller
      n = Math.max(0, n | 0);
      for (let i = 0; i < n; i++) step();
      updateHUD();
    },
    reset(seed){
      autoRun = false;               // stay paused for reproducible grading
      build(typeof seed === 'number' ? seed : undefined);
      updateHUD();
    },
    get elapsed(){ return elapsed; },
    get size(){ return { rows: ROWS, cols: COLS }; },
    get spawn(){ return { r: spawn.r, c: spawn.c }; },
    get exit(){ return { r: exit.r, c: exit.c }; },
    walls(r, c){
      const w = grid[r][c];
      return { n: w.n, e: w.e, s: w.s, w: w.w };
    },
    get bots(){ return bots; },
  };

  // ---------- on-page reset button (keeps the demo auto-playing) ----------
  document.getElementById('reset').addEventListener('click', function(){
    build(undefined);
    autoRun = true;
    lastTime = null;
    updateHUD();
  });

  // ---------- boot ----------
  build(undefined);
  updateHUD();
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
